import type { CSSProperties, HTMLAttributes } from "react";
import { cx } from "../utils/cx";

export type ProgressProps = Omit<HTMLAttributes<HTMLDivElement>, "children"> & {
  /** Current value; omit (or pass `undefined`) for an indeterminate bar. */
  value?: number;
  max?: number;
  /** Required: what is progressing. */
  "aria-label": string;
  tone?: "accent" | "success" | "warning" | "danger";
  size?: "sm" | "md";
  /** Show the percentage to the right. */
  showValue?: boolean;
};

const pct = (value: number, max: number) => (max > 0 ? Math.max(0, Math.min(100, (value / max) * 100)) : 0);

/** A linear progress bar. The fill eases to each new value; the indeterminate state is a slow sweep. */
export function Progress({
  value,
  max = 100,
  tone = "accent",
  size = "md",
  showValue,
  className,
  style,
  ...rest
}: ProgressProps) {
  const determinate = value !== undefined;
  const p = determinate ? pct(value, max) : 0;
  return (
    <div
      {...rest}
      role="progressbar"
      aria-valuemin={0}
      aria-valuemax={max}
      aria-valuenow={determinate ? value : undefined}
      className={cx("hm-progress", className)}
      data-tone={tone}
      data-size={size}
      data-indeterminate={determinate ? undefined : ""}
      style={{ "--_p": p / 100, ...style } as CSSProperties}
    >
      <span className="hm-progress-track">
        <span className="hm-progress-fill" />
      </span>
      {showValue && determinate ? <span className="hm-progress-value">{Math.round(p)}%</span> : null}
    </div>
  );
}

export type CircularProgressProps = Omit<ProgressProps, "size" | "showValue"> & {
  size?: "sm" | "md" | "lg";
  /** Content in the middle (a percentage, an icon). Hidden from assistive tech: the ring carries the value. */
  children?: React.ReactNode;
};

/** A ring. Same semantics as `Progress`; the arc eases to each value. */
export function CircularProgress({
  value,
  max = 100,
  tone = "accent",
  size = "md",
  className,
  style,
  children,
  ...rest
}: CircularProgressProps) {
  const determinate = value !== undefined;
  const p = determinate ? pct(value, max) : 25;
  return (
    <div
      {...rest}
      role="progressbar"
      aria-valuemin={0}
      aria-valuemax={max}
      aria-valuenow={determinate ? value : undefined}
      className={cx("hm-ring", className)}
      data-tone={tone}
      data-size={size}
      data-indeterminate={determinate ? undefined : ""}
      style={{ "--_p": p / 100, ...style } as CSSProperties}
    >
      <svg viewBox="0 0 36 36" aria-hidden="true">
        <circle className="hm-ring-track" cx="18" cy="18" r="15.5" />
        <circle className="hm-ring-arc" cx="18" cy="18" r="15.5" pathLength="1" />
      </svg>
      {children ? (
        <span className="hm-ring-label" aria-hidden="true">
          {children}
        </span>
      ) : null}
    </div>
  );
}
